def balanced_pairs(text):
    pairs = {")": "(", "]": "["}
    stack = []
    for mark in text:
        if mark == "(" or mark == "[":
            stack.append(mark)
        elif mark == ")" or mark == "]":
            if len(stack) == 0:
                return False
            if stack.pop() != pairs[mark]:
                return False
        else:
            return False
    return len(stack) == 0

print(balanced_pairs("([])[]"), balanced_pairs("([)]"), balanced_pairs("("))

